(()=>{const g=__game, {THREE}=__dbg; g.showScreen(null); g.mode='play'; g.player.release();
 // sample visible vertices of every moving obstacle mesh (in node-local space, transformed each frame)
 const samples=[]; for(const o of g.course.obstacles){ o.group.traverse(m=>{ if(!m.isMesh) return; const pos=m.geometry.attributes.position; const stepN=Math.max(1,Math.floor(pos.count/400)); const pts=[]; for(let i=0;i<pos.count;i+=stepN) pts.push(new THREE.Vector3().fromBufferAttribute(pos,i)); samples.push({o,m,pts}); }); }
 const w=new THREE.Vector3(), a=new THREE.Vector3(), b=new THREE.Vector3(), c=new THREE.Vector3(), ab=new THREE.Vector3();
 const R=0.22; // inner body core (smaller than the 0.28 collider) = clearly visible overlap
 const visInside=(p)=>{ const h=p.state==='slide'?0.85:1.76; a.set(p.pos.x,p.pos.y+R,p.pos.z); b.set(p.pos.x,p.pos.y+h-R,p.pos.z); ab.subVectors(b,a); const L=ab.lengthSq();
   for(const s of samples){ if(Math.abs(s.o.x-p.pos.x)>7) continue; for(const v of s.pts){ w.copy(v).applyMatrix4(s.m.matrixWorld); const t=Math.max(0,Math.min(1,w.clone().sub(a).dot(ab)/L)); c.copy(a).addScaledVector(ab,t); if(w.distanceTo(c)<R) return s.o.id; } } return null; };
 const report={}; let runs=0, frames=0;
 const starts=[{x:-4.6,y:1.4}, ...g.course.checkpoints];
 for (const cp of starts) for (let k=0;k<20;k++) { g.time=0; g.mode='play'; g.course.time=k*0.61+cp.x*0.07; g.player.respawn(cp); runs++;
   g.simulate(4,(t,p)=>{ if(p.state==='ground'||p.state==='air'||p.state==='slide'){ const id=visInside(p); frames++; if(id){ const key=id+' ('+p.state+')'; report[key]=(report[key]||0)+1; } } return {move:1}; }); }
 return {runs, framesChecked:frames, visible_passthrough_frames:report}})()
